  if (location.pathname !== '/me') {
    return <PagePlaceholder eyebrow="ACCOUNT" title="账号设置" description="偏好设置和安全管理会在这里逐步接入当前后端的个人中心接口。" primaryLabel="返回我的" primaryPath="/me" />;
